    "description": "\n      <p>Инструмент «Метка времени для PDF» добавляет в ваши PDF-документы доверенные метки времени по стандарту RFC 3161 с помощью внешних служб штампов времени (TSA). Это даёт юридически значимое математическое доказательство того, что документ существовал в определённом неизменном виде в точный момент времени.</p>\n      <p>Выбирайте из глобальных доверенных TSA-серверов, таких как DigiCert, Sectigo, SSL.com, FreeTSA или MeSign. Личные сертификаты для подписи не нужны, чтобы защитить ваши документы от будущих изменений.</p>\n      <p>Хеширование выполняется локально до обращения к серверу, поэтому содержимое документа остаётся полностью конфиденциальным.</p>\n    ",
