    "description": "\n      <p>Инструмент «Скрытие данных в PDF» — это наглядный интерактивный редактор для постоянного скрытия и защиты конфиденциальных данных в документах. Выделяйте мышью любые закрытые области — имена, адреса, номера документов, подписи, печати, финансовые данные или портреты — и применяйте закрашивание чёрным, белым, мозаику или размытие.</p>\n      <p>В отличие от обычных PDF-редакторов, которые лишь накладывают чёрные прямоугольники поверх текста, этот инструмент выполняет <strong>необратимую растеризацию на уровне пикселей</strong>. Текстовые слои, векторная графика и слои OCR уничтожаются полностью, и восстановить их копированием или обратной разработкой невозможно.</p>\n      <p>Кроме того, выполняется глубокая очистка метаданных: удаляются сведения об авторе, история создания и потоки XMP. Вся обработка идёт на 100% локально в вашем браузере, без загрузки на сервер.</p>\n    ",
