    "description": "\n      <p>Interactive Form Logic Designer — новаторский инструмент, который закрывает огромный пробел в возможностях PDF: создание активных, отзывчивых полей вместо плоских, «мёртвых» форм.</p>\n      <p>На нашем визуальном полотне со «светящимися стеклянными узлами» (на базе React Flow) поля формы представлены в виде связанных модулей. Перетаскивая связи, вы задаёте отношения: например, когда флажок установлен ➜ включить текстовое поле ➜ автоматически вычислить значения и обновить итоговое поле.</p>\n      <p>После проектирования движок AcroJS компилирует логику в официальный Acrobat JavaScript и внедряет её в словари '/AA' (Additional Actions) формы AcroForm. Интерактивное поведение затем выполняется нативно в любой стандартной программе для чтения PDF.</p>\n    ",
