    "description": "\n      <p>Исправление битых ссылок — глубокий структурный редактор, который обеспечивает работоспособность ссылок в опубликованных файлах.</p>\n      <p>Нерабочие адреса (404/500) в руководствах, технических документах и инструкциях снижают авторитет бренда. Этот инструмент позволяет удобно управлять всеми гиперссылками документа.</p>\n      <p>Он разбирает низкоуровневые словари <code>/Link</code> на каждой странице, проверяет ссылки и показывает их состояние в интерактивной таблице (красным — нерабочие, оранжевым — перенаправления). Просто введите новый адрес, и инструмент запишет его прямо в двоичный поток PDF.</p>\n    ",
